¿Qué se ve en el párrafo después de hacer clic en "Agregar"?

```jsx
function Lista() {
  const [items, setItems] = useState(["Pan"]);
  function agregar() {
    items.push("Leche");
    setItems(items);
  }
  return (
    <>
      <button onClick={agregar}>Agregar</button>
      <p>{items.length} productos</p>
    </>
  );
}
```

